# --- HELPER: GET LOCAL IP ---
def get_local_ip():
    try:
        gws = netifaces.gateways()
        default_iface = gws['default'][netifaces.AF_INET][1]
        ip_info = netifaces.ifaddresses(default_iface)[netifaces.AF_INET][0]
        return ip_info['addr']
    except:
        return "127.0.0.1"

# --- HELPER: YT-DLP EXTRACTOR ---
def extract_direct_url_with_ytdlp(url):
    """Attempt to extract direct video URL for supported sites"""
    if not YTDLP_AVAILABLE: return None
    ydl_opts = {
        'format': 'best',
        'quiet': True,
        'no_warnings': True,
        'simulate': True, # Do not download
        'skip_download': True
    }
    try:
        with yt_dlp.YoutubeDL(ydl_opts) as ydl:
            info = ydl.extract_info(url, download=False)
            return info.get('url', None)
    except Exception as e:
        logger.error(f"YTDLP Error: {e}")
        return None

# --- ACCOUNT MANAGER ---
class AccountManager:
    def __init__(self):
        self.accounts = {} 
        self.clients = {}  
        self.active_user_map = {} 
        self.load_accounts()

        env_user = os.getenv("PIKPAK_USER")
        env_pass = os.getenv("PIKPAK_PASS")
        if env_user and env_pass:
            self.add_account_credentials(env_user, env_pass)

    def load_accounts(self):
        if os.path.exists(ACCOUNTS_FILE):
            try:
                with open(ACCOUNTS_FILE, 'r') as f:
                    self.accounts = json.load(f)
            except Exception as e:
                logger.error(f"Failed to load accounts: {e}")

    def save_accounts(self):
        try:
            with open(ACCOUNTS_FILE, 'w') as f:
                json.dump(self.accounts, f)
        except Exception as e:
            logger.error(f"Failed to save accounts: {e}")

    def add_account_credentials(self, u, p):
        self.accounts[u] = p
        self.save_accounts()

    def get_accounts_list(self):
        return list(self.accounts.keys())

    async def get_client(self, tg_user_id):
        if not PIKPAK_AVAILABLE: return None
        username = self.active_user_map.get(str(tg_user_id))
        if not username:
            if self.accounts:
                username = list(self.accounts.keys())[0]
                self.active_user_map[str(tg_user_id)] = username
            else:
                return None

        if username in self.clients:
            return self.clients[username]

        password = self.accounts.get(username)
        if not password: return None

        try:
            logger.info(f"Logging in for {username}...")
            client = PikPakApi(username=username, password=password)
            await client.login()
            self.clients[username] = client
            return client
        except Exception as e:
            logger.error(f"Login failed for {username}: {e}")
            return None

    async def switch_account(self, tg_user_id, target_username):
        if target_username in self.accounts:
            self.active_user_map[str(tg_user_id)] = target_username
            await self.get_client(tg_user_id)
            return True
        return False

account_mgr = AccountManager()

# --- WEB SERVER ---
async def handle_player(request):
    file_id = request.query.get('id')
    user_id = request.query.get('user')
    if not file_id or not user_id: return web.Response(text="Missing parameters", status=400)
    client = await account_mgr.get_client(user_id)
    if not client: return web.Response(text="Bot not logged in", status=500)
    try:
        data = await client.get_download_url(file_id)
        video_url = data.get('url')
        filename = data.get('name', 'Video')
        if not video_url: return web.Response(text="Could not get link", status=404)
        html = f"""
        <!DOCTYPE html><html><head><title>{filename}</title><meta name="viewport" content="width=device-width, initial-scale=1">
        <style>body{{margin:0;background:#000;color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh}}video{{width:100%;max-width:1000px;max-height:90vh}}.info{{padding:10px;font-family:sans-serif}}a{{color:#00aaff;text-decoration:none}}</style>
        </head><body><video controls autoplay playsinline><source src="{video_url}" type="video/mp4">Not supported.</video>
        <div class="info"><h3>{filename}</h3><p><a href="{video_url}">Direct Link</a></p></div></body></html>
        """
        return web.Response(text=html, content_type='text/html')
    except Exception as e: return web.Response(text=f"Error: {e}", status=500)

async def start_web_server():
    app = web.Application()
    app.router.add_get('/play', handle_player)
    runner = web.AppRunner(app)
    await runner.setup()
    site = web.TCPSite(runner, '0.0.0.0', WEB_PORT)
    await site.start()
    logger.info(f"Web Player Server started on port {WEB_PORT}")

# --- AUTH ---
def get_whitelist():
    ids = [str(ADMIN_ID)]
    if os.path.exists(WHITELIST_FILE):
        with open(WHITELIST_FILE, 'r') as f:
            for line in f:
                if line.strip(): ids.append(line.strip())
    return ids

async def check_auth(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    user_id = str(update.effective_user.id)
    if user_id not in get_whitelist():
        await context.bot.send_message(chat_id=update.effective_chat.id, text=f"⛔ 无权访问 (ID: {user_id})")
        return False
    return True

