# --- CORE FUNCTIONS ---

async def generate_m3u_playlist(update, context, folder_id):
    """Generates M3U playlist for all videos in a folder"""
    user_id = update.effective_user.id
    client = await account_mgr.get_client(user_id)
    msg = await context.bot.send_message(update.effective_chat.id, "⏳ 正在生成 M3U 播放列表 (扫描前100个文件)...")

    try:
        # Limit to 100 to avoid timeouts
        resp = await client.file_list(parent_id=folder_id)
        files = resp.get('files', []) if isinstance(resp, dict) else resp

        m3u_content = "#EXTM3U\n"
        count = 0

        for f in files:
            if f.get('kind') == 'drive#folder': continue
            if f.get('mime_type', '').startswith('video/') or f.get('name', '').endswith(('.mp4', '.mkv', '.avi', '.mov')):
                try:
                    # Getting direct link for each file
                    d = await client.get_download_url(f['id'])
                    url = d.get('url')
                    name = f.get('name')
                    if url:
                        m3u_content += f"#EXTINF:-1,{name}\n{url}\n"
                        count += 1
                except: continue

        if count == 0:
            await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=msg.message_id, text="❌ 该目录下没有找到视频文件或无法获取链接。")
            return

        filename = f"playlist_{folder_id}.m3u"
        with open(filename, "w", encoding="utf-8") as f:
            f.write(m3u_content)

        await context.bot.send_document(
            chat_id=update.effective_chat.id,
            document=open(filename, "rb"),
            filename=filename,
            caption=f"✅ 已生成包含 {count} 个视频的播放列表"
        )
        os.remove(filename)
        await context.bot.delete_message(chat_id=update.effective_chat.id, message_id=msg.message_id)

    except Exception as e:
        await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=msg.message_id, text=f"❌ 生成失败: {e}")

async def cleanup_empty_folders(update, context):
    """Recursive empty folder cleanup"""
    client = await account_mgr.get_client(update.effective_user.id)
    status_msg = await context.bot.send_message(update.effective_chat.id, "🧹 正在扫描并清理空文件夹 (仅限根目录下的一级空文件夹)...")
    # Note: Full recursive cleanup is risky and time consuming in a bot interaction. 
    # This implementation focuses on shallow cleanup or simple empty check.
    try:
        files = await client.file_list(parent_id=None) # Root
        if isinstance(files, dict): files = files.get('files', [])

        deleted_count = 0
        for f in files:
            if f.get('kind') == 'drive#folder':
                # Check if empty
                # Some API versions expose 'size' for folders as 0 or empty contents
                # We try to list it.
                sub = await client.file_list(parent_id=f['id'])
                sub_files = sub.get('files', []) if isinstance(sub, dict) else sub

                if not sub_files:
                    await client.delete_file([f['id']])
                    deleted_count += 1

        await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=status_msg.message_id, text=f"✅ 清理完成: 删除了 {deleted_count} 个空文件夹")
    except Exception as e:
        await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=status_msg.message_id, text=f"❌ 清理失败: {e}")

