async def show_file_list(update: Update, context: ContextTypes.DEFAULT_TYPE, parent_id=None, page=0, edit_msg=False, search_query=None):
    user_id = update.effective_user.id
    client = await account_mgr.get_client(user_id)
    if not client:
        msg = "⚠️ 未登录。请 [👥 账号管理] -> [➕ 添加账号]"
        if edit_msg: await update.callback_query.edit_message_text(msg)
        else: await context.bot.send_message(update.effective_chat.id, msg)
        return

    try:
        kwargs = {}
        if parent_id: kwargs['parent_id'] = parent_id
        if search_query: kwargs['name'] = search_query

        resp = await client.file_list(**kwargs)
        files = resp.get('files', []) if isinstance(resp, dict) else (resp if isinstance(resp, list) else [])
        if not isinstance(files, list): files = []

        # Sort: Folders first
        files.sort(key=lambda x: (x.get('kind') != 'drive#folder', x.get('name')))

        items_per_page = 10
        total_items = len(files)
        start_idx = page * items_per_page
        end_idx = start_idx + items_per_page
        current_files = files[start_idx:end_idx]

        keyboard = []

        nav_top = []
        if parent_id or search_query:
            nav_top.append(InlineKeyboardButton("🏠 首页", callback_data="ls:"))
            nav_top.append(InlineKeyboardButton("🔙 返回", callback_data="ls:"))
        if nav_top: keyboard.append(nav_top)

        for f in current_files:
            name = f.get('name', 'Unknown')
            fid = f.get('id')
            kind = f.get('kind')
            display_name = (name[:20] + '..') if len(name) > 20 else name

            if kind == 'drive#folder':
                keyboard.append([InlineKeyboardButton(f"📁 {display_name}", callback_data=f"ls:{fid}")])
            else:
                size = f.get('size', 0)
                try: size_str = f"{int(size)/1024/1024:.1f}MB"
                except: size_str = "??"
                keyboard.append([InlineKeyboardButton(f"📄 {display_name} ({size_str})", callback_data=f"file:{fid}")])

        # Pagination
        nav_row = []
        s_q = search_query if search_query else ""
        p_id = parent_id if parent_id else ""
        if page > 0: nav_row.append(InlineKeyboardButton("⬅️ 上一页", callback_data=f"page:{p_id}:{page-1}:{s_q}"))
        if end_idx < total_items: nav_row.append(InlineKeyboardButton("下一页 ➡️", callback_data=f"page:{p_id}:{page+1}:{s_q}"))
        if nav_row: keyboard.append(nav_row)

        # Folder Actions (M3U)
        if parent_id and not search_query:
            keyboard.append([InlineKeyboardButton("📄 生成本目录 M3U 播放列表", callback_data=f"m3u:{parent_id}")])

        # Paste Actions
        if 'clipboard' in context.user_data:
            clip = context.user_data['clipboard']
            op = "移动" if clip['op'] == 'move' else "复制"
            keyboard.append([InlineKeyboardButton(f"📋 粘贴{op}", callback_data=f"paste:{p_id}"), InlineKeyboardButton("❌ 取消", callback_data="paste_cancel")])

        acc = account_mgr.active_user_map.get(str(user_id), "Unknown")
        title = f"👤 **{acc}**\n" + (f"🔍 **搜索**: `{search_query}`" if search_query else f"📂 **目录**: `{parent_id or 'ROOT'}`")
        text = f"{title}\n共 {total_items} 个项目"

        reply_markup = InlineKeyboardMarkup(keyboard)
        if edit_msg:
            try: await update.callback_query.edit_message_text(text=text, reply_markup=reply_markup, parse_mode='Markdown')
            except: pass
        else: await context.bot.send_message(update.effective_chat.id, text=text, reply_markup=reply_markup, parse_mode='Markdown')

    except Exception as e:
        logger.error(f"List error: {e}")
        if edit_msg: await update.callback_query.edit_message_text(f"❌ 读取失败: {e}")
        else: await context.bot.send_message(update.effective_chat.id, f"❌ 读取失败: {e}")

