async def handle_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    data = query.data
    user_id = update.effective_user.id

    parts = data.split(':', 1)
    cmd = parts[0]
    arg = parts[1] if len(parts) > 1 else None

    if cmd == "ls": await show_file_list(update, context, parent_id=(arg if arg else None), edit_msg=True)
    elif cmd == "file": await show_file_options(update, context, arg)
    elif cmd == "page":
        p = arg.split(':')
        await show_file_list(update, context, parent_id=(p[0] or None), page=int(p[1]), edit_msg=True, search_query=(p[2] if len(p)>2 else None))
    elif cmd == "m3u":
        await generate_m3u_playlist(update, context, arg)
    elif cmd == "act_link":
        client = await account_mgr.get_client(user_id)
        try:
            d = await client.get_download_url(arg)
            if d.get('url'): await context.bot.send_message(update.effective_chat.id, f"🔗 **直链**:\n`{d['url']}`", parse_mode='Markdown')
        except: pass
    elif cmd == "act_cut":
        context.user_data['clipboard'] = {'id': arg, 'op': 'move'}
        await query.answer("✂️ 已剪切")
        await show_file_list(update, context, edit_msg=True)
    elif cmd == "paste":
        clip = context.user_data.get('clipboard')
        if clip:
            client = await account_mgr.get_client(user_id)
            try:
                await client.move_file(file_ids=[clip['id']], parent_id=(arg if arg else None))
                del context.user_data['clipboard']
                await query.answer("✅ 移动成功")
                await show_file_list(update, context, parent_id=arg, edit_msg=True)
            except Exception as e: await query.answer(f"失败: {e}", show_alert=True)
    elif cmd == "paste_cancel":
        if 'clipboard' in context.user_data: del context.user_data['clipboard']
        await show_file_list(update, context, edit_msg=True)
    elif cmd == "act_del":
        client = await account_mgr.get_client(user_id)
        try:
            await client.delete_file([arg])
            await query.edit_message_text("🗑 已删除")
        except: await query.answer("删除失败")
    elif cmd == "act_ren":
        context.user_data['renaming_id'] = arg
        await context.bot.send_message(update.effective_chat.id, "✏️ 回复新文件名:", reply_markup=ForceReply(selective=True))
    elif cmd == "acc_switch":
        if await account_mgr.switch_account(user_id, arg):
            await query.answer(f"✅ 切换至: {arg}")
            await show_accounts_menu(update, context)
        else: await query.answer("切换失败")
    elif cmd == "acc_add": await context.bot.send_message(update.effective_chat.id, "➕ 发送: `/login 用户 密码`", parse_mode='Markdown')
    elif cmd == "close_menu": await query.delete_message()
    elif cmd == "task_del":
        client = await account_mgr.get_client(user_id)
        try: 
            if hasattr(client, 'delete_offline_task'): await client.delete_offline_task([arg])
            elif hasattr(client, 'offline_delete'): await client.offline_delete([arg])
            await query.answer("已删除")
            await show_offline_tasks(update, context)
        except: await query.answer("不支持删除")
    elif cmd == "tasks_refresh":
        await query.delete_message()
        await show_offline_tasks(update, context)

