async def text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not await check_auth(update, context): return
    msg = update.message.text.strip()
    user_id = update.effective_user.id

    if 'renaming_id' in context.user_data:
        client = await account_mgr.get_client(user_id)
        try:
            await client.rename_file(file_id=context.user_data['renaming_id'], name=msg)
            await context.bot.send_message(update.effective_chat.id, f"✅ 重命名成功")
        except Exception as e: await context.bot.send_message(update.effective_chat.id, f"❌ 失败: {e}")
        del context.user_data['renaming_id']
        return

    # Regex Rename State
    if 'regex_state' in context.user_data:
        # Expected format: "pattern replacement"
        try:
            parts = msg.split(' ', 1)
            if len(parts) < 2: raise ValueError("格式错误")
            pattern, repl = parts[0], parts[1]
            client = await account_mgr.get_client(user_id)
            # Fetch current folder files
            parent_id = context.user_data['regex_state'].get('parent_id')
            files_resp = await client.file_list(parent_id=parent_id)
            files = files_resp.get('files', []) if isinstance(files_resp, dict) else files_resp

            count = 0
            for f in files:
                old_name = f.get('name')
                new_name = re.sub(pattern, repl, old_name)
                if old_name != new_name:
                    await client.rename_file(file_id=f['id'], name=new_name)
                    count += 1
            await context.bot.send_message(update.effective_chat.id, f"✅ 已批量重命名 {count} 个文件")
        except Exception as e:
             await context.bot.send_message(update.effective_chat.id, f"❌ 操作失败: {e}")
        del context.user_data['regex_state']
        return

    if msg == "📂 文件管理": await show_file_list(update, context)
    elif msg == "👥 账号管理": await show_accounts_menu(update, context)
    elif msg == "📉 离线任务": await show_offline_tasks(update, context)
    elif msg == "🧹 垃圾清理": 
        await context.bot.send_message(update.effective_chat.id, "🧹 请选择清理操作:", reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🗑 清空回收站", callback_data="cmd_trash_empty")],
            [InlineKeyboardButton("📁 清理空文件夹", callback_data="cmd_clean_empty")]
        ]))
    elif msg == "⚙️ 批量重命名":
        context.user_data['regex_state'] = {'parent_id': None} # Default to root, or track current path better in future
        await context.bot.send_message(update.effective_chat.id, "⚙️ **批量重命名 (正则)**\n请输入: `Regex模式 替换文本`\n例如: `\[AD\] ""` (去除[AD])", parse_mode='Markdown')
    elif msg == "☁️ 空间状态":
        client = await account_mgr.get_client(user_id)
        if client:
            info = await client.get_quota_info()
            limit = int(info.get('quota', 0))
            usage = int(info.get('usage', 0))
            await context.bot.send_message(update.effective_chat.id, f"☁️ {int(usage/1024**3)}GB / {int(limit/1024**3)}GB")
    elif msg == "🔍 搜索文件": await context.bot.send_message(update.effective_chat.id, "🔍 回复关键词:", reply_markup=ForceReply(selective=True))
    elif update.message.reply_to_message and "搜索" in update.message.reply_to_message.text: await show_file_list(update, context, search_query=msg)
    elif msg == "➕ 添加任务": await context.bot.send_message(update.effective_chat.id, "📥 发送链接 (Magnet, HTTP, TikTok...) 或发送 .txt 文件批量下载")
    elif "http" in msg or "magnet:" in msg:
        client = await account_mgr.get_client(user_id)
        if client:
            urls = msg.split('\n')
            count = 0
            for url in urls:
                if not url.strip(): continue
                final_url = url
                # Social Media Parsing
                if YTDLP_AVAILABLE and any(x in url for x in ['tiktok.com', 'twitter.com', 'x.com', 'youtube.com', 'instagram.com']):
                    direct = extract_direct_url_with_ytdlp(url)
                    if direct: final_url = direct
                try:
                    await client.offline_download(final_url)
                    count += 1
                except: pass
            await context.bot.send_message(update.effective_chat.id, f"✅ 已添加 {count} 个任务")

async def document_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle TXT file for batch download"""
    if not await check_auth(update, context): return
    doc = update.message.document
    if doc.mime_type == 'text/plain' or doc.file_name.endswith('.txt'):
        file = await doc.get_file()
        content = await file.download_as_bytearray()
        links = content.decode('utf-8').splitlines()

        client = await account_mgr.get_client(update.effective_user.id)
        if not client: return

        count = 0
        msg = await context.bot.send_message(update.effective_chat.id, f"📥 正在解析批量文件 ({len(links)} 行)...")

        for link in links:
            link = link.strip()
            if not link: continue
            try:
                await client.offline_download(link)
                count += 1
            except: pass

        await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=msg.message_id, text=f"✅ 批量导入完成: {count} 个任务")

async def command_callback_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle special cleanup commands"""
    query = update.callback_query
    await query.answer()
    if query.data == "cmd_trash_empty":
        client = await account_mgr.get_client(update.effective_user.id)
        try:
            await client.trash_empty()
            await query.edit_message_text("✅ 回收站已清空")
        except: await query.edit_message_text("❌ 清空失败")
    elif query.data == "cmd_clean_empty":
        await cleanup_empty_folders(update, context)

