                await client.trash_empty()
            else:
                raise Exception("API method not found (check pikpakapi version)")

            await query.edit_message_text("✅ 回收站已清空")
        except Exception as e:
            await query.answer(f"❌ 清空失败: {e}", show_alert=True)

