# --- TEXT ROUTER ---
async def router_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not await check_auth(update, context): return
    msg = update.message.text.strip()
    user_id = update.effective_user.id

    # Print debug info
    print(f"[Router Text] User: {user_id}, Msg: {msg}")

    # --- 1. STATE HANDLING (Higher Priority) ---

    if context.user_data.get('adding_account'):
        await process_add_account(update, context, msg)
        return

    if context.user_data.get('renaming_id'):
        client = await account_mgr.get_client(user_id)
        try:
            await client.rename_file(file_id=context.user_data['renaming_id'], name=msg)
            await context.bot.send_message(update.effective_chat.id, "✅ 重命名成功")
        except Exception as e: await context.bot.send_message(update.effective_chat.id, f"❌ 失败: {e}")
        del context.user_data['renaming_id']
        return

    if context.user_data.get('regex_context'):
        await process_regex_rename(update, context, msg)
        return

    if context.user_data.get('searching'):
        del context.user_data['searching'] # One-time flag
        await show_file_list(update, context, search_query=msg)
        return

    # --- 2. MENU COMMANDS ---

    if msg == "📂 文件管理": await show_file_list(update, context)

    elif msg == "👥 账号管理": await show_accounts_menu(update, context)

    elif msg == "📉 离线任务": await show_offline_tasks(update, context)

    elif msg == "☁️ 空间/VIP": await show_quota_info(update, context)

    elif msg == "🛠 极客工具箱":
        kb = [
            [InlineKeyboardButton("🗂️ AList 服务信息", callback_data="tool_alist")],
            [InlineKeyboardButton("🧹 清理本地下载缓存", callback_data="tool_clearcache")]
        ]
        await context.bot.send_message(
            update.effective_chat.id, 
            "🛠 **极客工具箱**",
            reply_markup=InlineKeyboardMarkup(kb)
        )

    elif msg == "🧹 垃圾清理":
        kb = [[InlineKeyboardButton("🗑 确认清空回收站", callback_data="trash_empty")]]
        await context.bot.send_message(update.effective_chat.id, "⚠️ 确认要清空回收站吗？操作不可恢复。", reply_markup=InlineKeyboardMarkup(kb))

    elif msg == "🔍 搜索文件":
        context.user_data['searching'] = True
        await context.bot.send_message(update.effective_chat.id, "🔍 请发送搜索关键词 (支持 `re:` 正则表达式):", reply_markup=ForceReply(selective=True))

    elif msg == "➕ 添加任务":
        await context.bot.send_message(update.effective_chat.id, "📥 请直接发送链接 (Magnet/HTTP) 或上传 .txt 文件")

    # --- 3. AUTO-DETECT LINKS ---
    elif "http" in msg or "magnet:" in msg:
        await add_download_task(update, context, msg)

    # --- 4. FALLBACK ---
    else:
        # Check reply to search
        if update.message.reply_to_message and "搜索" in update.message.reply_to_message.text:
             await show_file_list(update, context, search_query=msg)

import os
import json
from .config import ACCOUNTS_FILE, logger

PIKPAK_AVAILABLE = True
try:
    from pikpakapi import PikPakApi
except ImportError:
    PIKPAK_AVAILABLE = False
    logger.warning("pikpakapi library not found.")

class AccountManager:
    def __init__(self):
        self.accounts = {}  # {username: password}
        self.clients = {}   # {username: PikPakApi}
        self.active_user_map = {} # {tg_user_id: username}
        self.load_accounts()

        # Load from Env
        env_user = os.getenv("PIKPAK_USER")
        env_pass = os.getenv("PIKPAK_PASS")
        if env_user and env_pass:
            self.add_account_credentials(env_user, env_pass)

    def load_accounts(self):
        if os.path.exists(ACCOUNTS_FILE):
            try:
                with open(ACCOUNTS_FILE, 'r') as f:
                    self.accounts = json.load(f)
            except Exception as e:
                logger.error(f"Failed to load accounts: {e}")

    def save_accounts(self):
        try:
            with open(ACCOUNTS_FILE, 'w') as f:
                json.dump(self.accounts, f)
        except Exception as e:
            logger.error(f"Failed to save accounts: {e}")

    def add_account_credentials(self, u, p):
        self.accounts[u] = p
        self.save_accounts()

    def remove_account(self, u):
        if u in self.accounts:
            del self.accounts[u]
            if u in self.clients:
                del self.clients[u]
            # Reset active user map for users using this account
            for uid, user in list(self.active_user_map.items()):
                if user == u:
                    del self.active_user_map[uid]
            self.save_accounts()
            return True
        return False

    def get_accounts_list(self):
        return list(self.accounts.keys())

    async def get_client(self, tg_user_id, specific_username=None):
        """
        Get or create authenticated client.
        If specific_username is provided, gets client for that user (ignoring active map).
        """
        if not PIKPAK_AVAILABLE: 
            logger.error("PikPak API library not installed.")
            return None

        username = specific_username
        if not username:
            # Determine active username
            username = self.active_user_map.get(str(tg_user_id))
            if not username:
                if self.accounts:
                    username = list(self.accounts.keys())[0]
                    self.active_user_map[str(tg_user_id)] = username
                else:
                    return None

        # Return existing session
        if username in self.clients:
            return self.clients[username]

        # Login new session
        password = self.accounts.get(username)
        if not password: return None

        try:
            logger.info(f"Logging in for {username}...")
            client = PikPakApi(username=username, password=password)
            await client.login()
            self.clients[username] = client
            return client
        except Exception as e:
            logger.error(f"Login failed for {username}: {e}")
            return None

    async def switch_account(self, tg_user_id, target_username):
        if target_username in self.accounts:
            self.active_user_map[str(tg_user_id)] = target_username
            # Warm up connection
            client = await self.get_client(tg_user_id)
            return client is not None
        return False

