    context.user_data['adding_account'] = True

    text = (
        "👤 **添加新账号**\n\n"
        "请直接回复账号和密码 (用空格分隔)\n"
        "例如: `user@test.com password123`\n\n"
        "提示: 回复 `cancel` 取消操作"
    )
    # Using ForceReply ensures the client focuses input
    await context.bot.send_message(
        update.effective_chat.id, 
        text, 
        reply_markup=ForceReply(selective=True), 
        parse_mode='Markdown'
    )
    if update.callback_query: await update.callback_query.answer()

async def process_add_account(update, context, text):
    logger.info(f"Adding account process: {text[:5]}***")

    if text.lower() == "cancel" or text == "取消":
        del context.user_data['adding_account']
        await context.bot.send_message(update.effective_chat.id, "🚫 操作已取消")
        return

    try:
        # Robust split: handles space, tab, newline, and chinese space
        cleaned_text = text.replace("：", " ").replace(":", " ")
        parts = cleaned_text.split()

        if len(parts) < 2:
            await context.bot.send_message(
                update.effective_chat.id, 
                "❌ **格式错误**\n请确保输入了账号和密码，并用空格分开。\n请重新回复，或回复 `cancel` 取消。", 
                parse_mode='Markdown'
            )
            # Do NOT delete state, allow retry
            return

        email = parts[0].strip()
        password = parts[1].strip()

        # Privacy delete
        try: await update.message.delete()
        except: pass

        msg = await context.bot.send_message(update.effective_chat.id, f"⏳ 正在验证账号 `{email}` ...", parse_mode='Markdown')

        # Add to manager
        account_mgr.add_account_credentials(email, password)

        # Try login
        if await account_mgr.switch_account(update.effective_user.id, email):
             await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=msg.message_id, text="🎉 **登录成功！**\n该账号已激活。")
             # Only clear state on success
             if 'adding_account' in context.user_data: del context.user_data['adding_account']
        else:
             await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=msg.message_id, text="⚠️ **验证失败**\n账号已保存，但登录失败 (可能是密码错误)。\n您可以尝试重新输入正确的密码。")
             # State remains active for retry

    except Exception as e:
        logger.error(f"Add account exception: {e}")
        await context.bot.send_message(update.effective_chat.id, f"❌ 程序错误: {e}")
        if 'adding_account' in context.user_data: del context.user_data['adding_account']

async def show_quota_info(update, context):
    user_id = update.effective_user.id
    msg = await context.bot.send_message(update.effective_chat.id, "⏳ 正在查询...")

    try:
        client = await account_mgr.get_client(user_id)
        if not client:
            await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=msg.message_id, text="❌ 未登录")
            return

        info = await client.get_quota_info()
        limit = int(info.get('quota', 1))
        usage = int(info.get('usage', 0))

        if limit == 0: limit = 1
        percent = (usage / limit) * 100
        bars = int(percent / 10)
        if bars > 10: bars = 10
        progress_bar = "🟦" * bars + "⬜" * (10 - bars)

        try:
            me = await client.get_user_info()
            vip_status = "👑 VIP" if me.get('vip_status') == 'ok' else "👤 免费用户"
            expire = me.get('vip_expire', 'N/A')
            nickname = me.get('name', 'Unknown')
        except:
            vip_status, expire, nickname = ("Unknown", "-", "-")

        text = (
            f"📊 **空间详情**\n\n"
            f"用户: `{nickname}`\n"
            f"等级: {vip_status} (到期: {expire})\n\n"
            f"已用: `{format_bytes(usage)}`\n"
            f"总量: `{format_bytes(limit)}`\n"
            f"`[{progress_bar}] {percent:.1f}%`"
        )

        await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=msg.message_id, text=text, parse_mode='Markdown')

    except Exception as e:
        await context.bot.edit_message_text(chat_id=update.effective_chat.id, message_id=msg.message_id, text=f"❌ 查询失败: {e}")

